with $\alpha_1$ defined in \eqref{alpha1} and $\alpha_2  \triangleq\frac {\sigma+2\ell} {m^2 \gamma}  \tilde\theta_\text{max}^2$. Using the Gronwall Bellman Inequality, \eqref{a2:a2} implies that 
\begin{equation}\label{forapp}
V(e,\tilde\theta)\leq \left( V(e(0),\tilde\theta(0))-\frac{\alpha_2}{\alpha_1}\right)\exp(-\alpha_1 t) + \frac{\alpha_2}{\alpha_1}. 
\end{equation}
Thus, $e$ exponentially converges to the set defined by the following inequality
\begin{equation*}{\lim_{t\rightarrow\infty} {e(t)^TPe(t)} \leq \frac{1} {\gamma} \tilde\theta_\text{max}^2}.\end{equation*}
Using the bound in Lemma \ref{ambarbound}(ii) we have that 
\begin{equation}\label{ePe} e^TPe\geq \frac 1 {2(s+\ell) }\norm e^2,\end{equation} 
then we can conclude that
$\lim_{t\rightarrow\infty}\norm {e(t)}^2 \leq \beta_1 \tilde\theta_\text{max}^2 $
where $\beta_1$ is defined in \eqref{b1}. The boundedness of $\theta(t)$ follows from Theorem \ref{thm:proj}.

From \eqref{forapp} and \eqref{ePe}, we know that
\begin{equation*}
\norm {e(t)}^2 \leq  k_0 \exp \left(-\frac{\sigma+2\ell}{m^2} t \right) + k_1
\end{equation*}
where
\begin{equation}\label{k01}\begin{split}
k_0 =&   \frac{2(s+\ell) m^2 }{\sigma+2\ell}\norm{e(0)}^2 + \frac{2(s+\ell)}{\gamma } \norm{\tilde\theta(0)}^2  - k_1\\
k_1 = & \frac{2(s+\ell)}{\gamma }\tilde\theta_\text{max}^2 .
\end{split}\end{equation}
Using the following inequalities
\begin{equation*}
 \frac{2(s+\ell) m^2 }{\sigma+2\ell}  \leq \frac{2sm^2 }{\sigma} \text{ and }
 \frac{2(s+\ell)}{\gamma} \leq \frac{2s}{\sigma} \frac{\sigma+\ell}{\gamma}
\end{equation*}
the fact that $\norm{\tilde\theta(0)}\leq\tilde \theta_\text{max}$ and the definition of $\rho$ from \eqref{rhos}, the result in \eqref{e2e} holds with
\begin{equation}
\kappa_1 =   \frac{2sm^2 }{\sigma} \text{ and }
\kappa_2 =  \frac{2s}{\sigma}.
\end{equation}

Beginning with \begin{equation}\begin{split}\label{elfirst}
\norm{e(t)}_{L_2}^2 \leq & \int_0^\infty - \dot V(e(t),\tilde\theta(t)) \leq V(e(0),\tilde\theta(0)) \\
\leq& \frac{m^2}{\sigma+ 2\ell} \norm{e(0)}^2 + \frac{1}{\gamma}{\norm{\tilde\theta(0)}}^2,
